/* First-run selection only. Existing valid settings always win. */
#include <stdlib.h>
static const DWORD rrPreset[5][2]={{0,0},{960,720},{1440,1080},{1920,1440},{2880,2160}};
static int rr_display_fit(DWORD w,DWORD h){int selected=0;for(int i=1;i<5;i++)if(rrPreset[i][0]<=w&&rrPreset[i][1]<=h)selected=i;return selected;}
static int rr_display_screen(DWORD *w,DWORD *h){DEVMODEA mode={0};mode.dmSize=sizeof(mode);if(EnumDisplaySettingsA(NULL,ENUM_CURRENT_SETTINGS,&mode)&&mode.dmPelsWidth&&mode.dmPelsHeight){*w=mode.dmPelsWidth;*h=mode.dmPelsHeight;}else{int x=GetSystemMetrics(SM_CXSCREEN),y=GetSystemMetrics(SM_CYSCREEN);*w=x>0?(DWORD)x:640;*h=y>0?(DWORD)y:480;}return rr_display_fit(*w,*h);}
static BOOL rr_display_number(const char *path,const char *key,DWORD *out){char text[64],*end;DWORD n=GetPrivateProfileStringA("render",key,"",text,sizeof(text),path);if(!n||n>=sizeof(text)-1)return FALSE;unsigned long value=strtoul(text,&end,10);if(end==text)return FALSE;while(*end==' '||*end=='\t')end++;if(*end)return FALSE;*out=value;return TRUE;}
static BOOL rr_display_existing(const char *path,DWORD *w,DWORD *h,BOOL *windowed,BOOL *fast){DWORD x,y;if(!rr_display_number(path,"width",&x)||!rr_display_number(path,"height",&y))return FALSE;if(!((x==0&&y==0)||(x>=640&&x<=3840&&y>=480&&y<=2160&&!(x%2)&&!(y%2))))return FALSE;*w=x;*h=y;*windowed=GetPrivateProfileIntA("render","windowed",0,path)!=0;*fast=GetPrivateProfileIntA("render","fast_output",1,path)!=0;return TRUE;}
static BOOL rr_display_create(const char *path,DWORD w,DWORD h){if(lstrlenA(root)>MAX_PATH-64)return FALSE;char temp[MAX_PATH],data[192];int n=wsprintfA(temp,"%s\\rr-display-first-%u-%u.tmp",root,GetCurrentProcessId(),GetTickCount());if(n<=0||n>=MAX_PATH)return FALSE;HANDLE file=CreateFileA(temp,GENERIC_WRITE,0,NULL,CREATE_NEW,FILE_ATTRIBUTE_TEMPORARY,NULL);if(file==INVALID_HANDLE_VALUE)return FALSE;int bytes=wsprintfA(data,"[render]\r\nwidth=%u\r\nheight=%u\r\nwindowed=0\r\nfast_output=1\r\n",w,h);DWORD done=0;BOOL ok=WriteFile(file,data,bytes,&done,NULL)&&done==(DWORD)bytes;if(ok)ok=FlushFileBuffers(file);CloseHandle(file);if(ok)ok=MoveFileExA(temp,path,MOVEFILE_WRITE_THROUGH);if(!ok)DeleteFileA(temp);return ok;}
static void rr_display_initialize(const char *path,DWORD *w,DWORD *h,BOOL *windowed,BOOL *fast){if(rr_display_existing(path,w,h,windowed,fast)){trace("Display settings source=existing; no automatic rewrite");return;}DWORD sw,sh;int selected=rr_display_screen(&sw,&sh);*w=rrPreset[selected][0];*h=rrPreset[selected][1];*windowed=FALSE;*fast=TRUE;BOOL exists=GetFileAttributesA(path)!=INVALID_FILE_ATTRIBUTES;BOOL saved=!exists&&rr_display_create(path,*w,*h);if(!saved&&!exists&&rr_display_existing(path,w,h,windowed,fast)){trace("Display settings source=concurrent existing; no automatic rewrite");return;}char line[192];wsprintfA(line,"Display settings source=auto desktop=%ux%u render=%ux%u saved=%d existingInvalidRetained=%d",sw,sh,*w,*h,saved,exists);trace(line);}
